21:         private Action SigleWorkUIAction { get; set; }
22: 
23:         /// <summary>
24:         /// 构造函数
25:         /// </summary>
26:         public BaseMachine()
27:         {
28:             this.TraceSignal = new Signal("单步跟踪信号");
29:             this.SingleSignal = new Signal("单颗信号");
30:             this.PauseSignal = new Signal("暂停信号");
31:         }
32: 
33:         #region 信号及控制
34:         /// <summary>
35:         /// 单步跟踪信号
36:         /// </summary>
37:         [JsonIgnore]
38:         public Signal TraceSignal { get; set; }
39: 
40:         /// <summary>
41:         /// 设备暂停信号
42:         /// </summary>
43:         [JsonIgnore]
44:         public Signal PauseSignal { get; set; }
45: 
46:         /// <summary>
47:         /// 单颗信号
48:         /// </summary>
49:         [JsonIgnore]
50:         public Signal SingleSignal { get; set; }
51: 
52:         /// <summary>
53:         /// 是否是单步跟踪模式
54:         /// </summary>
55:         [JsonIgnore]
56:         private bool IsTraceMode => MachineStateModel.GetInstance().IsSingleStepWork;
57: 
58:         /// <summary>
59:         /// 单颗工作的通知
60:         /// </summary>
61:         /// <param name="action">通知Action</param>
62:         /// <param name="control">通知控件</param>
63:         public void SetSingleWorkAction(Action action, Control control)
64:         {
65:             this.SigleWorkUIAction = () => control.BeginInvoke(action);
66:         }
67: 
68:         public void ClearWorkAction()
69:         {
70:             this.SigleWorkUIAction = null;
71:         }
72: 
73:         /// <summary>
74:         /// 设置成单步跟踪模式
75:         /// </summary>
76:         public void TraceWork()
77:         {
78:             MachineStateModel.GetInstance().MachineState = MachineStateEnum.Working;
79:             MachineStateModel.GetInstance().IsSingleStepWork = true;
80:         }
81: 
82:         /// <summary>
83:         /// 单步等待
84:         /// </summary>
85:         /// <returns>是否等到信号</returns>
86:         public bool TraceWait()
87:         {
88:             if (this.IsTraceMode)
89:             {
90:                 this.TraceSignal.Wait();
91:             }
92: 
93:             return true;
94:         }
95:         
96:         /// <summary>
97:         /// 下一步
98:         /// </summary>
99:         /// <returns>发送信号的结果</returns>
100:         /// <exception cref="InvalidOperationException">信号发送失败异常</exception>
101:         public bool NextStep()
102:         {
103:             if (this.IsTraceMode)
104:             {
105:                 this.TraceSignal.Set();
106:             }
107: 
108:             return true;
109:         }
110: 
111:         /// <summary>
112:         /// 暂停工作
113:         /// </summary>
114:         public void PauseWork()
115:         {
116:             MachineStateModel.GetInstance().MachineState = MachineStateEnum.Pause;
117:         }
118: 
119:         /// <summary>
120:         /// 开始工作
121:         /// </summary>
122:         public void StartWork()
123:         {
124:             MachineStateModel.GetInstance().MachineState = MachineStateEnum.Working;
125:             //Alarmer.SetRunState();
126:         }
127: 
128:         /// <summary>
129:         /// 继续工作
130:         /// </summary>
131:         public void ContinueWork()
132:         {
133:             MachineStateModel.GetInstance().MachineState = MachineStateEnum.Working;
134:             this.PauseSignal.Set();
135:             //Alarmer.SetRunState();
136:         }
137: 
138:         /// <summary>
139:         /// 停止工作
140:         /// </summary>
141:         public void StopWork()
142:         {
143:             MachineStateModel.GetInstance().MachineState = MachineStateEnum.Stop;
144:             //MachineStateModeSingleton.GetInstance().MachineWorkMode = MachineWorkModeEnum.StepWork;
145:             this.ClearWorkAction();
146:             //Alarmer.SetStopState();
147:         }
148: 
149:         #endregion
150: 
151:         /// <summary>
152:         /// 是否退出软件
153:         /// </summary>
154:         [JsonIgnore]
155:         public bool IsExitApp { get; set; } 
156: 
157:         /// <summary>
158:         /// 程序退出时执行
159:         /// </summary>
160:         public void ExitApp()
161:         {
162:             MachineStateModel.GetInstance().MachineState = MachineStateEnum.Stop;
163:             RuntimeProvider.ThreadFlag = false;
164:             this.IsExitApp = true;
165:         }
166:     }
167: }

