662:         public void StartBackGroundThread()
663:         {
664:             if (this.BackGroundThreadThread == null || !this.BackGroundThreadThread.IsAlive)
665:             {
666:                 this.BackGroundThreadThread = new Thread(
667:                                   () =>
668:                                   {
669:                                       while (RuntimeProvider.ThreadFlag)
670:                                       {
671:                                           // 检测是否安全门关闭，安全门关闭则允许设备工作
672:                                           this.StartCheckSafeDoorTask();
673: 
674:                                           // 检测激光干涉尺状态
675:                                           this.StartLaserEncoderCheckTask();
676: 
677:                                           // 长时间未操作登出高级权限账户
678:                                           this.AutoLogOut();
679: 
680:                                           // 后台加热检测
681:                                           this.BackgroundTemperatureAlarm();
682: 
683:                                           // 后台耗材检测
684:                                           ConsumablesProgram.GetInstance().BackgroundConsumable();
685: 
686:                                           // 后台信号检测
687:                                           NeedScanSensorPool.GetInstance().StartScan();
688: 
689:                                           // 存图
690:                                           VisionService.StartSaveThread();
691: 
692:                                           // 存数据库
693:                                           StatisticsService.StartSaveThread();
694: 
695:                                           Thread.Sleep(100);
696:                                       }
697:                                   })
698:                 { Name = "后台监控线程", IsBackground = true };
699:                 this.BackGroundThreadThread.Start();
700:             }

