372:                 if (MachineHardwareConfiguration.GetInstance().IsStaticWaffleConfigrated & WaferSubDevicePara.GetInstance().WaferTableDevicePara.IsNeedReCreateStateWithStaticAdapterTablet)
373:                 {
374:                     WaferSubDevicePara.GetInstance().WaferTableDevicePara.CreateStateWithStaticAdapterTablet();
375:                     WaferSubDevicePara.GetInstance().WaferTableDevicePara.CurrentStaticAdapterTablet.SlotState = SlotStatuEnum.Good;
376:                     WaferSubDevicePara.GetInstance().WaferTableDevicePara.CurrentStaticAdapterTablet?.AdapterState?.SetAllSlotState(SlotStatuEnum.Good);
377:                     WaferSubDevicePara.GetInstance().WaferTableDevicePara.ResetNeedReCreateStateWithStaticAdapterTabletSignal();
378:                 }
379: 
380:                 // 生成magazine状态
381:                 if (WaferSubDevicePara.GetInstance().MagazineDevicePara.IsNeedReCreateState/* && WaferSubDevicePara.GetInstance().MagazineDevicePara.IsUseMagazineLift*/)
382:                 {
383:                     this.WaferSystemProgram.MagazineAllocationsProgram.CurrentAllocationsConfig?.SetAllSlotState(SlotStatuEnum.Good);
384: 
385:                     if (WaferSubDevicePara.GetInstance().WaferTableDevicePara.CurrentTablet is WaferTablet wt)
386:                     {
387:                         wt.InitTabletInfo();
388:                     }
389:                     else if (WaferSubDevicePara.GetInstance().WaferTableDevicePara.CurrentTablet is AdapterTablet adt)
390:                     {
391:                         adt.CreateAdapterEntity();
392:                         adt.AdapterState.SetAllSlotState(SlotStatuEnum.Good);
393:                     }
394: 
395:                     WaferSubDevicePara.GetInstance().MagazineDevicePara.ResetNeedReCreateStateSignal();
396:                 }
397: 
398:                 if (!WaferSubController.GetInstance().WaferTableController.IsInCollisionCircle(WaferSubController.GetInstance().WaferTableController.WaferTableG0Pos))
399:                 {
400:                     // 确保顶针在安全状态
401:                     WaferSubController.GetInstance().EjectController.ReturnEjection();
402:                     WaferSubController.GetInstance().WaferTableController.MoveWaferTableToReadyPosition();
403:                 }
404: 
405:                 return true;
406:             }
407:             catch (Exception e)
408:             {
409:                 AKRSXtraMessageBox.Show($"{e.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
410:                 return false;
411:             }

