55:     /// <summary>
56:     /// 单例Json
57:     /// </summary>
58:     /// <typeparam name="T">类</typeparam>
59:     public abstract class SingletonJson<T> where T : class, new()
60:     {
61:         /// <summary>
62:         /// 锁对象
63:         /// </summary>
64:         public static object locker = new object();
65: 
66:         /// <summary>
67:         /// 示例
68:         /// </summary>
69:         protected static T instance;
70: 
71:         /// <summary>
72:         /// 路径
73:         /// </summary>
74:         public static string FilePath;
75: 
76:         /// <summary>
77:         /// 获取实例
78:         /// </summary>
79:         /// <returns>单例实例</returns>
80:         public static T GetInstance()
81:         {
82:             lock (locker)
83:             {
84:                 if (instance == null)
85:                 {
86:                     Load();
87:                 }
88: 
89:                 if (instance == null)
90:                 {
91:                     instance = new T();
92:                 }
93: 
94:                 return instance;
95:             }
96:         }
97: 
98:         /// <summary>
99:         /// 加载
100:         /// </summary>
101:         public static void Load()
102:         {
103:             instance = new T();
104:             instance = JsonFormatHelper<T>.ReadGenericObject(FilePath);
105:         }
106: 
107:         /// <summary>
108:         /// 保存
109:         /// </summary>
110:         public void Save()
111:         {
112:             lock (locker)
113:             {
114:                 JsonFormatHelper<T>.SaveGenericObject(instance, FilePath);
115:                 JsonFormatHelper<T>.CopyFile(FilePath, Path.GetDirectoryName(FilePath) + "Baks", true, 50);
116:             }
117:         }

