84:         public AKRSPoint3D ForwardConvertCoordinate(AKRSPoint3D value)
85:         {
86:             AKRSPoint3D point = new AKRSPoint3D();
87:             
88:             if (this.Type == CoordinateSystemTypeEnum.General)
89:             {
90:                 point.X = this.Distance.X + (value.X * Math.Cos(this.Degree) - value.Y * Math.Sin(this.Degree));
91: 
92:                 point.Y = this.Distance.Y + (value.X * Math.Sin(this.Degree) + value.Y * Math.Cos(this.Degree));
93: 
94:                 point.Z = value.Z + this.Distance.Z;
95:             }
96:             else if (this.Type == CoordinateSystemTypeEnum.Vm)
97:             {
98:                 if (this.CCalibTransTool == null)
99:                 {
100:                    this.CCalibTransTool = TransformTool.GetCCalibTransTool(this.Name);
101:                 }
102: 
103:                 point = TransformTool.GetPoint3D(CCalibTransTool, value, this.CalibModule);
104: 
105:                 // 赋值 Z
106:                 point.Z = value.Z + this.Distance.Z;
107:             }
108: 
109:             return point;

coord-inverse.code:
140:         public AKRSPoint3D BackConvertCoordinate(AKRSPoint3D value)
141:         {
142:             AKRSPoint3D point = new AKRSPoint3D();
143: 
144:             if (this.Type == CoordinateSystemTypeEnum.General)
145:             {
146:                 double distanceX = value.X - this.Distance.X;
147:                 double distanceY = value.Y - this.Distance.Y;
148: 
149:                 double length = Math.Sqrt(distanceX * distanceX + distanceY * distanceY);
150: 
151:                 double degree = Math.Atan2(distanceY, distanceX);
152: 
153:                 point.X = length * Math.Cos(degree - this.Degree);
154:                 point.Y = length * Math.Sin(degree - this.Degree);
155:                 point.Z = value.Z - this.Distance.Z;
156:             }
157:             else if (this.Type == CoordinateSystemTypeEnum.Vm)
158:             {
159:                 throw new InvalidOperationException("不支持海康标定的逆运算");
160:             }
161: 
162:             return point;

