215:         public void AutoFocus(AKRSCamera camera, Axis axisZ, double pLimit, double nLimit)
216:         {
217:             int T = 0;
218:    
219: 
220:             List<double> posList = new List<double>();
221:             List<double> sharpnessList = new List<double>();
222: 
223:             axisZ.AbsoluteMove(nLimit);
224:             double distance = (pLimit - nLimit) / 5;
225: 
226:             double pulse = distance / 5;
227:             while (true)
228:             {
229:                 
230: 
231:                 axisZ.RelativeMove(distance);
232:                 // 获取当前图像
233:                 Bitmap bitmap = camera.SnapImage(false, false);
234:                 Rectangle Roi = new Rectangle();     // 需要对焦的区域
235:                 // 计算清晰度得分
236:                 double currentArticulation = this.CalSharpnessVm(bitmap);
237:                 posList.Add(axisZ.GetRealPosition());
238:                 sharpnessList.Add(currentArticulation);
239: 
240:                 if((axisZ.GetRealPosition() + distance) > pLimit)
241:                 {
242:                     break;
243:                 }
244:             }
245: 
246:             double max = sharpnessList[0];
247:             int index = 0;
248:             for (int i = 0; i < sharpnessList.Count; i++)
249:             {
250:                 if (sharpnessList[i] >= max)
251:                 {
252:                     max = sharpnessList[i];
253:                     index = i;
254:                 }
255:             }
256: 
257:             axisZ.AbsoluteMove(posList[index]);

