272:                 if (focusL.Count == 1 ) // 这里是第一次运动
273:                 {
274:                     axisZ.RelativeMove(pulse); 
275:                     continue;
276:                 }
277:                 // 前两张确认调焦方向
278:                 if (focusL.Count == 2)
279:                 {
280:                     if (currentArticulation > focusL[focusL.Count - 2]) // 判断是否跑对方向
281:                     {
282:                         pulse *= 1; // 对的方向
283:                         axisZ.RelativeMove(pulse);
284:                     }
285:                     else
286:                     {
287:                         pulse *= -1; // 不对的方向我们相反就可以了
288:                         axisZ.RelativeMove(pulse * 1);   // 这里不是跑回原来的位置，而是更过去一些，节约时间
289:                     }
290: 
291:                     continue;
292:                 }
293: 
294:                 // 清晰度大于前一张图
295:                 if (currentArticulation > focusL[focusL.Count - 2])
296:                 {
297:                     axisZ.RelativeMove(pulse);
298:                 }
299:                 else
300:                 {
301: 
302:                     // 返回峰值，跳出循环
303:                     if (T == Round)
304:                     {
305:                         break; // 两轮结束了，跳出循环
306:                     }
307:                     pulse *= -0.5;
308:                     goto label;
309: 
310:                 }
311:             }
312:         }

