396:         public CMvdImage BitmapToCMvdImage(Bitmap bmpInputImg)
397:         {
398:             CMvdImage cMvdImage = new CMvdImage();
399:             System.Drawing.Imaging.PixelFormat bitPixelFormat = bmpInputImg.PixelFormat;
400:             BitmapData bmData = bmpInputImg.LockBits(new Rectangle(0, 0, bmpInputImg.Width, bmpInputImg.Height), ImageLockMode.ReadOnly, bitPixelFormat);//锁定
401: 
402:             if (bitPixelFormat == System.Drawing.Imaging.PixelFormat.Format8bppIndexed)
403:             {
404:                 Int32 bitmapDataSize = bmData.Stride * bmData.Height;//bitmap图像缓存长度
405:                 int offset = bmData.Stride - bmData.Width;
406:                 Int32 ImageBaseDataSize = bmData.Width * bmData.Height;
407:                 byte[] _BitImageBufferBytes = new byte[bitmapDataSize];
408:                 byte[] _ImageBaseDataBufferBytes = new byte[ImageBaseDataSize];
409:                 Marshal.Copy(bmData.Scan0, _BitImageBufferBytes, 0, bitmapDataSize);
410:                 int bitmapIndex = 0;
411:                 int ImageBaseDataIndex = 0;
412:                 for (int i = 0; i < bmData.Height; i++)
413:                 {
414:                     for (int j = 0; j < bmData.Width; j++)
415:                     {
416:                         _ImageBaseDataBufferBytes[ImageBaseDataIndex++] = _BitImageBufferBytes[bitmapIndex++];
417:                     }
418:                     bitmapIndex += offset;
419:                 }
420:                 MVD_IMAGE_DATA_INFO stImageData = new MVD_IMAGE_DATA_INFO();
421:                 stImageData.stDataChannel[0].nRowStep = (uint)bmData.Width;
422:                 stImageData.stDataChannel[0].nLen = (uint)ImageBaseDataSize;
423:                 stImageData.stDataChannel[0].nSize = (uint)ImageBaseDataSize;
424:                 stImageData.stDataChannel[0].arrDataBytes = _ImageBaseDataBufferBytes;
425:                 cMvdImage.InitImage((uint)bmData.Width, (uint)bmData.Height, MVD_PIXEL_FORMAT.MVD_PIXEL_MONO_08, stImageData);
426:             }
427:             else if (bitPixelFormat == System.Drawing.Imaging.PixelFormat.Format24bppRgb)
428:             {
429:                 Int32 bitmapDataSize = bmData.Stride * bmData.Height;//bitmap图像缓存长度
430:                 int offset = bmData.Stride - bmData.Width * 3;
431:                 Int32 ImageBaseDataSize = bmData.Width * bmData.Height * 3;
432:                 byte[] _BitImageBufferBytes = new byte[bitmapDataSize];
433:                 byte[] _ImageBaseDataBufferBytes = new byte[ImageBaseDataSize];
434:                 Marshal.Copy(bmData.Scan0, _BitImageBufferBytes, 0, bitmapDataSize);
435:                 int bitmapIndex = 0;
436:                 int ImageBaseDataIndex = 0;
437:                 for (int i = 0; i < bmData.Height; i++)
438:                 {
439:                     for (int j = 0; j < bmData.Width; j++)
440:                     {
441:                         _ImageBaseDataBufferBytes[ImageBaseDataIndex++] = _BitImageBufferBytes[bitmapIndex + 2];
442:                         _ImageBaseDataBufferBytes[ImageBaseDataIndex++] = _BitImageBufferBytes[bitmapIndex + 1];
443:                         _ImageBaseDataBufferBytes[ImageBaseDataIndex++] = _BitImageBufferBytes[bitmapIndex];
444:                         bitmapIndex += 3;
445:                     }
446:                     bitmapIndex += offset;
447:                 }
448:                 MVD_IMAGE_DATA_INFO stImageData = new MVD_IMAGE_DATA_INFO();
449:                 stImageData.stDataChannel[0].nRowStep = (uint)bmData.Width * 3;
450:                 stImageData.stDataChannel[0].nLen = (uint)ImageBaseDataSize;
451:                 stImageData.stDataChannel[0].nSize = (uint)ImageBaseDataSize;
452:                 stImageData.stDataChannel[0].arrDataBytes = _ImageBaseDataBufferBytes;
453:                 cMvdImage.InitImage((uint)bmData.Width, (uint)bmData.Height, MVD_PIXEL_FORMAT.MVD_PIXEL_RGB_RGB24_C3, stImageData);
454:             }
455:             bmpInputImg.UnlockBits(bmData);  // 解除锁定
456:             return cMvdImage;
457:         }

