calib-affine.code:
202:         public static void NPointTrans(
203:             List<AKRSPoint2D> originalPoints,
204:             List<AKRSPoint2D> transformedPoints,
205:             out HTuple homMatTrans)
206:         {
207:             HTuple px = new HTuple();
208:             HTuple py = new HTuple();
209:             HTuple qx = new HTuple();
210:             HTuple qy = new HTuple();
211: 
212:             for (int i = 0; i < originalPoints.Count; i++)
213:             {
214:                 px = px.TupleConcat(originalPoints[i].X);
215:                 py = py.TupleConcat(originalPoints[i].Y);
216:             }
217: 
218:             for (int i = 0; i < transformedPoints.Count; i++)
219:             {
220:                 qx = qx.TupleConcat(transformedPoints[i].X);
221:                 qy = qy.TupleConcat(transformedPoints[i].Y);
222:             }
223: 
224:             HOperatorSet.VectorToHomMat2d(px, py, qx, qy, out homMatTrans);
225:         }

