154:         public static void FitCircle(
155:             List<AKRSPoint2D> points,
156:             out double centerX,
157:             out double centerY,
158:             out double radius)
159:         {
160:             HObject circleContour;
161:             HOperatorSet.GenEmptyObj(out circleContour);
162: 
163:             HTuple rows = new HTuple();
164:             HTuple columns = new HTuple();
165: 
166:             foreach (var point in points)
167:             {
168:                 rows = rows.TupleConcat(point.Y);
169:                 columns = columns.TupleConcat(point.X);
170:             }
171: 
172:             HOperatorSet.GenContourPolygonXld(out circleContour, rows, columns);
173: 
174:             HOperatorSet.FitCircleContourXld(
175:                 circleContour,
176:                 "algebraic",
177:                 -1,
178:                 0,
179:                 0,
180:                 3,
181:                 2,
182:                 out HTuple hv_Row,
183:                 out HTuple hv_Col,
184:                 out HTuple hv_Radius,
185:                 out HTuple hv_StartPhi,
186:                 out HTuple hv_EndPhi,
187:                 out HTuple hv_PointOrder);
188: 
189:             centerX = hv_Col.D;
190:             centerY = hv_Row.D;
191:             radius = hv_Radius.D;
192: 
193:             circleContour.Dispose();
194:         }

