bm-safe-level.code:
337:         public double GetBondheadSafeLevel(AKRSPoint3D targetPos)
338:         {
339:             // 获取当前平台上的TU
340:             TransportUnit transportUnit =
341:                 TransportDomain.GetInstance().TransportProgram.BondSubSectionProgram.TransportUnit;
342: 
343:             // 当前位置
344:             AKRSPoint3D curPos = this.bondModule.Get3DRealPosition();
345: 
346:             // 安全高度转到G0坐标系
347:             double safeHeight = this.bondModule.BondCoordinateSystem
348:                 .SelfPosToG0(this.bondDevicePara.BondHeadParam.AxisSafePos).Z;
349: 
350:             if (transportUnit != null)
351:             {
352:                 // 如果固晶区点胶气缸弹下来，则用点胶气缸的高度
353:                 if (MachineHardwareConfiguration.GetInstance().IsSystem2Dispense
354:                     && System2Domain.GetInstance().S2DispenseController.IsDispenseHeightMeasurementOpen()
355:                     && System2Domain.GetInstance().BondProgram.S2DispenserProgram.Dispenser != null)
356:                 {
357:                     safeHeight = transportUnit.CoordinateSystem.SelfPosToG0(new AKRSPoint3D()).Z
358:                                  + ProductConfiguration.GetInstance().TransportUnitConfig.SafeHeight - System2Domain
359:                                      .GetInstance().S2DispenseController.DistanceForBondHandAndDispenser.Z;
360:                 }
361:                 else
362:                 {
363:                     safeHeight = transportUnit.CoordinateSystem.SelfPosToG0(new AKRSPoint3D()).Z
364:                                  + ProductConfiguration.GetInstance().TransportUnitConfig.SafeHeight
365:                                  + (this.bondModule.BondHead.CurrentNozzle?.MeasureHeightOffset ?? 0);
366:                 }
367: 
368:                 safeHeight = this.bondModule.ConvertG0ToMachinePos(safeHeight);
369:             }
370:             else
371:             {
372:                 safeHeight = this.bondModule.ConvertG0ToMachinePos(safeHeight);
373:             }
374: 
375:             if (Machine.GetInstance().IsWorking() == false)
376:             {
377:                 // 非工作状态安全高度置为轴安全高度
378:                 safeHeight = this.bondDevicePara.BondHeadParam.AxisSafePos.Z;
379:             }
380: 
381:             if (MachineHardwareConfiguration.GetInstance().IsStaticWaffleConfigrated)
382:             {
383:                 AKRSPoint3D avoidPos = this.bondModule.ConvertG0ToMachinePos(
384:                     WaferSubDevicePara.GetInstance().WaferTableDevicePara.BondAvoidStaticWafflePos);
385: 
386:                 if (targetPos.Y >= avoidPos.Y || curPos.Y >= avoidPos.Y)
387:                 {
388:                     double nozzleOffset = this.bondModule.BondHead.CurrentNozzle != null
389:                                               ? this.bondModule.BondHead.CurrentNozzle.MeasureHeightOffset
390:                                               : 0;
391: 
392:                     double staticWaffleLevel = avoidPos.Z + nozzleOffset;
393: 
394:                     // 静态华夫盒高度高于安全高度时，安全高度提升到静态华夫盒高度
395:                     safeHeight = staticWaffleLevel > safeHeight ? staticWaffleLevel : safeHeight;
396:                 }
397:             }
398: 
399:             if (safeHeight > this.bondModule.BondHead.AxisZ.AxisSetPara.PLimit
400:                 || safeHeight < this.bondModule.BondHead.AxisZ.AxisSetPara.NLimit)
401:             {
402:                 throw new Exception("载具安全高度过高，超出轴极限，请重新设置载具的安全高度");
403:             }
404: 
405:             return safeHeight;

