66:         public AKRSPoint3D GetBondCompensate(double x, double y)
67:         {
68:             if (!MachineSoftwareConfiguration.GetInstance().IsBondCompensate)
69:             {
70:                 return new AKRSPoint3D();
71:             }
72: 
73:             if (this.TransportUnitCompensateX == null || this.TransportUnitCompensateY == null)
74:             {
75:                 return new AKRSPoint3D();
76:             }
77: 
78:             // 计算偏移值
79:             double offsetX = x - this.StartPoint.X;
80:             double offsetY = y - this.StartPoint.Y;
81: 
82:             // 计算在哪个区间
83:             int indexX = (int)(offsetX / this.ColumnSpacing);
84:             int indexY = (int)(offsetY / this.RowSpacing);
85: 
86:             double offsetDistanceX = offsetX % this.ColumnSpacing;
87:             double offsetDistanceY = offsetY % this.RowSpacing;
88: 
89:             int xAdd = 1;
90:             int yAdd = 1;
91: 
92:             if (indexX < 0)
93:             {
94:                 indexX = 0;
95:             } 
96:             else if (indexX >= this.TransportUnitCompensateX.GetLength(1) - 1)
97:             {
98:                 indexX = this.TransportUnitCompensateX.GetLength(1) - 1;
99:                 xAdd = 0;
100:             }
101: 
102:             if (indexY < 0)
103:             {
104:                 indexY = 0;
105:             }
106:             else if (indexY >= this.TransportUnitCompensateX.GetLength(0) - 1)
107:             {
108:                 indexY = this.TransportUnitCompensateX.GetLength(0) - 1;
109:                 yAdd = 0;
110:             }
111: 
112:             double x1 = this.TransportUnitCompensateX[indexY, indexX];
113:             double y1 = this.TransportUnitCompensateY[indexY, indexX];
114:             double x2 = this.TransportUnitCompensateX[indexY, indexX + xAdd];
115:             double y2 = this.TransportUnitCompensateY[indexY, indexX + xAdd];
116:             double x3 = this.TransportUnitCompensateX[indexY + yAdd, indexX];
117:             double y3 = this.TransportUnitCompensateY[indexY + yAdd, indexX];
118:             double x4 = this.TransportUnitCompensateX[indexY + yAdd, indexX + xAdd];
119:             double y4 = this.TransportUnitCompensateY[indexY + yAdd, indexX + xAdd];
120: 
121:             // 插值法
122:             double interpolationX1 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * x1
123:                                      + offsetDistanceX / this.ColumnSpacing * x2;
124: 
125:             double interpolationY1 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * y1
126:                                      + offsetDistanceX / this.ColumnSpacing * y2;
127: 
128:             double interpolationX2 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * x3
129:                                      + offsetDistanceX / this.ColumnSpacing * x4;
130: 
131:             double interpolationY2 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * y3
132:                                      + offsetDistanceX / this.ColumnSpacing * y4;
133: 
134:             double interpolationX = (this.RowSpacing - offsetDistanceY) / this.RowSpacing * interpolationX1
135:                                     + offsetDistanceY / this.RowSpacing * interpolationX2;
136: 
137:             double interpolationY = (this.RowSpacing - offsetDistanceY) / this.RowSpacing * interpolationY1
138:                                     + offsetDistanceY / this.RowSpacing * interpolationY2;
139: 
140:             if (Math.Abs(interpolationX) > 1 || Math.Abs(interpolationY) > 1)
141:             {
142:                 throw new Exception("贴片补偿过大，有问题");
143:             }
144: 
145:             return new AKRSPoint3D(interpolationX, interpolationY, 0);

