94:         public (double, double) GetAxisCompensate(double x, double y)
95:         {
96:             if (x > this.StartPoint3D.X + this.ColumnSpacing * this.ColumnCount || x < this.StartPoint3D.X
97:                 || y > this.StartPoint3D.Y + this.RowSpacing * this.RowCount || y < this.StartPoint3D.Y)
98:             {
99:                 throw new Exception("补偿范围超极限");
100:             }
101: 
102:             // 计算偏移值
103:             double offsetX = x - this.StartPoint3D.X;
104:             double offsetY = y - this.StartPoint3D.Y;
105: 
106:             // 计算在哪个区间
107:             int indexX = (int)(offsetX / this.ColumnSpacing);
108:             int indexY = (int)(offsetY / this.RowSpacing);
109: 
110:             double offsetDistanceX = offsetX % this.ColumnSpacing;
111:             double offsetDistanceY = offsetY % this.RowSpacing;
112: 
113:             double x1 = this.CompensateX[indexY, indexX];
114:             double y1 = this.CompensateY[indexY, indexX];
115:             double x2 = this.CompensateX[indexY, indexX + 1];
116:             double y2 = this.CompensateY[indexY, indexX + 1];
117:             double x3 = this.CompensateX[indexY + 1, indexX];
118:             double y3 = this.CompensateY[indexY + 1, indexX];
119:             double x4 = this.CompensateX[indexY + 1, indexX + 1];
120:             double y4 = this.CompensateY[indexY + 1, indexX + 1];
121: 
122:             // 插值法
123:             double interpolationX1 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * x1
124:                                      + offsetDistanceX / this.ColumnSpacing * x2;
125: 
126:             double interpolationY1 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * y1
127:                                      + offsetDistanceX / this.ColumnSpacing * y2;
128: 
129:             double interpolationX2 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * x3
130:                                      + offsetDistanceX / this.ColumnSpacing * x4;
131: 
132:             double interpolationY2 = (this.ColumnSpacing - offsetDistanceX) / this.ColumnSpacing * y3
133:                                      + offsetDistanceX / this.ColumnSpacing * y4;
134: 
135:             double interpolationX = (this.RowSpacing - offsetDistanceY) / this.RowSpacing * interpolationX1
136:                                     + offsetDistanceY / this.RowSpacing * interpolationX2;
137: 
138:             double interpolationY = (this.RowSpacing - offsetDistanceY) / this.RowSpacing * interpolationY1
139:                                     + offsetDistanceY / this.RowSpacing * interpolationY2;
140: 
141:             interpolationX = interpolationX / 10000.0;
142:             interpolationY = interpolationY / 10000.0;
143: 
144:             if (Math.Abs(interpolationX) > 1 || Math.Abs(interpolationY) > 1)
145:             {
146:                 throw new Exception("补偿值过大");
147:             }
148: 
149:             return (interpolationX, interpolationY);
150:         }
151: 
152:         /// <summary>
153:         /// 获取焊头的补偿
154:         /// 相机和焊头之间有一段距离，数据都来自相机，所有焊头要减去偏移值
155:         /// </summary>
156:         /// <param name="x">点位X</param>
157:         /// <param name="y">点位Y</param>
158:         /// <param name="offset">相机和焊头之间的距离</param>
159:         /// <returns>结果</returns>
160:         public AKRSPoint3D GetBondHandCompensate(double x, double y, AKRSPoint3D offset)
161:         {
162:             // 获取相机的补偿
163:             (double, double) camera = this.GetAxisCompensate(x, y);
164: 
165:             // 获取焊头的补偿
166:             (double, double) bond = this.GetAxisCompensate(x - offset.X, y - offset.Y);
167: 
168:             // 返回差值
169:             return new AKRSPoint3D(camera.Item1 - bond.Item1, camera.Item2 - bond.Item2, 0);

