318:             iGroup.ipolBegin();
319: 
320:             // 设置为绝对坐标系 ，不设置绝对坐标系
321:             iGroup.ipolSetAbsMode(true, -1);
322: 
323:             iGroup.ipolTanVelocity(0.05);
324:             iGroup.ipolTanAcceleration(0.5);
325:             iGroup.ipolTanDeceleration(0.5);
326: 
327:             // 设置抖动时间，不知道什么意思
328:             iGroup.ipolTanJerkTime(0.01);
329: 
330:             iGroup.ipolLine(x / 1000.0, y / 1000.0);
331: 
332:             // 等待插补结束
333:             iGroup.ipolWaitMovement(100000);
334: 
335:             // 退出插补模式
336:             iGroup.ipolEnd();
337:         }
338:         else
339:         {
340:             this.bondModule.MoveBondXY(x, y);
341:         }
342:     }
