sr-center.code:
310:         private void MoveToCameraCenter(string prName)
311:         {
312:             // 寻找Pr模板
313:             PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance().Find(prName);
314: 
315:         RetryCommand:
316: 
317:             Thread.Sleep(200);
318: 
319:             // 执行定位
320:             ExcuteResult p1Result = pREntity.DoWork();
321: 
322:             // 定位失败，直接返回
323:             if (p1Result != ExcuteResult.Success)
324:             {
325:                 AKRSXtraMessageBox.Show("Vision fail");
326:                 return;
327:             }
328: 
329:             // 定位结果
330:             MatchResult matchResult = (MatchResult)pREntity.AlgResult;
331: 
332:             if (Math.Abs(matchResult.CenterX - 1224) < 0.1 && Math.Abs(matchResult.CenterY - 1024) < 0.1)
333:             {
334:                 return;
335:             }
336: 
337:             // 相机中心移动
338:             double x = this.bondModule.BondAxisX.GetCmdPosition()
339:                        - (1224 - matchResult.CenterX) * (double)this.SpinX.Value;
340:             double y = this.bondModule.BondAxisY.GetCmdPosition()
341:                        + (1024 - matchResult.CenterY) * (double)this.SpinY.Value;
342: 
343:             // 移动到相机中心
344:             this.bondModule.BondAxisX.AbsoluteMove(x);
345:             this.bondModule.BondAxisY.AbsoluteMove(y);
346: 
347:             Thread.Sleep(100);
348: 
349:             goto RetryCommand;

