233:         public bool CreateSoftkeyProcess()
234:         {
235:             try
236:             {
237:                 Process[] ps = Process.GetProcessesByName(SOFTKEY_PROCESS_NAME);
238:                 if (ps != null && ps.Length > 0)
239:                 {
240:                     foreach (Process p in ps)
241:                     {
242:                         if (p != null && !p.HasExited)
243:                         {
244:                             p.Kill();
245:                             p.Dispose();
246:                         }
247:                     }
248:                 }
249:                 //启用BGx86进程
250:                 hGBx86 = new Process();
251:                 //启动命令中写入mmf名称和更新间隔时间
252:                 szMmfId = Guid.NewGuid().ToString();
253:                 hGBx86.StartInfo = new ProcessStartInfo()
254:                 {
255:                     FileName = SOFTKEY_PROCESS_NAME + ".exe",
256:                     Arguments = szMmfId + " " + TIME_DELAY.ToString()
257:                 };
258:                 hGBx86.Start();
259: 
260:                 threadReadkey = new Thread(ThreadReadKey);
261:                 threadReadkey.IsBackground = true;
262:                 threadReadkey.Start();
263:                 while (firstRead)
264:                 {
265:                     if (this.errorMessage != SoftkeyErrorMessage.NoError)
266:                     {
267:                         return false;
268:                     }
269:                     Thread.Sleep(10);
270:                 }
271:             }
272:             catch (Exception e)
273:             {
274:                 log.Error("加密锁通信进程启动失败");
275:                 log.Error(e);
276:                 this.errorMessage = SoftkeyErrorMessage.ConnectError;
277:                 return false;
278:             }
279:             return true;
280:         }

