291:                     if (st.m_iUserId == 0)
292:                     {
293:                         curNoKeyTimes++;
294:                         if (curNoKeyTimes < MAX_NOKEY_TIME)
295:                         {
296:                             //可能是偶尔发的读错，重新读
297:                             Thread.Sleep(10);
298:                             continue;
299:                         }
300:                     }
301:                     try
302:                     {
303:                         userId = st.m_iUserId;
304:                         if (userId == 0)
305:                         {
306:                             this.errorMessage = SoftkeyErrorMessage.Nokey;
307:                             return;
308:                         }
309:                         curNoKeyTimes = 0;
310:                         limitTime = new DateTime(st.m_lLimitTime);
311:                         lastTime = new DateTime(st.m_lLastCheckTime);
312:                     }
313:                     catch (Exception e)
314:                     {
315:                         log.Error("授权时间格式错误");
316:                         log.Error(e);
317:                         this.errorMessage = SoftkeyErrorMessage.TimeError;
318:                         return;
319:                     }
320:                     firstRead = false;
321:                     Thread.Sleep(TIME_DELAY);
322:                 }
323:                 catch (Exception e)
324:                 {
325:                     curErrorTimes++;
326:                     if (curErrorTimes < MAX_ERROR_TIME)
327:                     {
328:                         Thread.Sleep(1000);
329:                         continue;
330:                     }
331:                     log.Error("加密锁通信失败");
332:                     log.Error(e);
333:                     this.errorMessage = SoftkeyErrorMessage.ConnectError;
334:                     return;
335:                 }
336:             }
