241:         private void AppendLog(string message)
242:         {
243:             try
244:             {
245:                 string timeStamp = DateTime.Now.ToString("yy-MM-dd HH:mm:ss-fff");
246:                 if (this.listViewLog.Items.Count > 10000)
247:                 {
248:                     this.listViewLog.Items.Clear();
249:                 }
250: 
251:                 if (this.listViewLog.InvokeRequired)
252:                 {
253:                     this.listViewLog.BeginInvoke(new Action(() =>
254:                     {
255:                         listViewLog.Items.Insert(0, new ListViewItem(new string[] { timeStamp, message }));
256:                     }));
257:                 }
258:                 else
259:                 {
260:                     this.listViewLog.Items.Insert(0, new ListViewItem(new string[] { timeStamp, message }));
261:                 }
262: 
263:                 if (!Directory.Exists("./log"))
264:                 {
265:                     Directory.CreateDirectory("./log");
266:                 }
267:                 using (FileStream fs = new FileStream("./log/LocateDemoCs.log", FileMode.Append))
268:                 {
269:                     using (StreamWriter sw = new StreamWriter(fs))
270:                     {
271:                         sw.WriteLine(timeStamp + ":" + message);
272:                     }
273:                 }
274:             }
275:             catch (Exception ex)
276:             {
277:                 throw new Exception(ex.Message);
278:             }
279:         }

