1152:                         moveDriveY.quickStop(Dsa.QS_PROGRAMMED_DEC, Dsa.QS_BYPASS | Dsa.QS_STOP_SEQUENCE);
1153:                         ///Wait that motor is stopped
1154:                         moveDriveY.waitMovement(60000);
1155:                     }
