408:         private DockPanel GetDockPanel(string controlName)
409:         {
410:             DockPanel dockPanel = null;
411: 
412:             foreach (DockPanel dockManagerPanel in this.dockManager.Panels)
413:             {
414:                 Control[] cs = dockManagerPanel.Controls.Find(controlName, true);
415: 
416:                 if (cs.Any())
417:                 {
418:                     dockPanel = dockManagerPanel;
419:                     break;
420:                 }
421:             }
422: 
423:             return dockPanel;
424:         }
