430:         /// <param name="createUserControlAction">DockPanel 里包含的组件</param>
431:         public void ShowPanel(string controlName, Func<XtraUserControl> createUserControlAction)
432:         {
433:             DockPanel dockPanel = this.GetDockPanel(controlName);
434: 
435:             if (dockPanel != null)
436:             {
437:                 Form form = dockPanel.ParentForm;
438: 
439:                 if (form != null)
