120:         /// </summary>
121:         public void RefreshTrees()
122:         {
123:             MagazineAllocationsConfig allocationsTemp = WaferSystemProgram.GetInstance().MagazineAllocationsProgram.CurrentAllocationsConfig;
124: 
125:             if (allocationsTemp == null)
126:             {
127:                 allocationsTemp = new MagazineAllocationsConfig();
128:             }
129: 
130:             this.list.Clear();
131:             int index = 0;
132:             int parentIndex = 0;
133: 
134:             for (int i = 0; i < allocationsTemp.MaxUseLayerCount; i++)
135:             {
136:                 parentIndex = index;
137:                 if (allocationsTemp.TabletArray[i] is WaferTablet)
138:                 {
139:                     WaferTablet wt = (WaferTablet)allocationsTemp.TabletArray[i];
140:                     this.list.Add(new Node() { Id = index, ParentId = parentIndex, Name = $"Slot{i + 1}: {wt.Name}" });
141:                     index++;
142:                 }
143:                 else if (allocationsTemp.TabletArray[i] is AdapterTablet)
144:                 {
145:                     AdapterTablet ad = (AdapterTablet)allocationsTemp.TabletArray[i];
146:                     this.list.Add(new Node() { Id = index, ParentId = parentIndex, Name = $"Slot{i + 1}: {ad.Name}" });
147:                     index++;
148: 
149:                     for (int j = 0; j < ad.AdapterSetting.MaxUseWaffleCount; j++)
150:                     {
151:                         this.list.Add(new Node() { Id = index, ParentId = parentIndex, Name = $"{index} - {ad.AdapterSetting.WaffleArray[j].Name}" });
152:                         index++;
153:                     }
154:                 }
155:                 else if (allocationsTemp.TabletArray[i] is NullTablet)
156:                 {
157:                     this.list.Add(new Node() { Id = index, ParentId = parentIndex, Name = $"Slot{i + 1}:" });
158:                     index++;
159:                 }
160:             }
161: 
162:             this.GcWaferMagazine.Controls.Clear();
163:             this.GcWaferMagazine.Refresh();
164:             this.GcWaferMagazine.Controls.Add(this.treeList);
165:         }
