343:                 {
344:                     // 是否在换静态华夫盒避让位
345:                     bool isOnChangeStaticWaffleAvoidancePos = false;
346: 
347:                     // 超时返回False
348:                     while (!SignalPool.GetInstance().IsWaferAllowPickSignal.Wait(100))
349:                     {
350:                         // 判断是否需要换静态华夫盒
