360: 
361:                                 isOnChangeStaticWaffleAvoidancePos = true;
362:                             }
363:                         }
364: 
365:                         // 点停止返回Abort
366:                         if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
367:                         {
368:                             return ExcuteResult.Abort;
369:                         }
370:                     }
371:                 }
372:                 else
373:                 {
