379:                         if (!SignalPool.GetInstance().IsWaferAllowPickSignal.Wait())
380:                         {
381:                             return ExcuteResult.Abort;
382:                         }
383:                     }
384:                 }
385:             }
386:             else
387:             {
388:                 // 翻转台允许取料信号,这个信号会自动复位
389:                 if (!SignalPool.GetInstance().IsFlipTableAllowPickSignal.Wait())
390:                 {
391:                     return ExcuteResult.Abort;
392:                 }
393:             }
394: 
395:             //if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Pause)
396:             //{
397:             //    Machine.GetInstance().Continue();
398:             //}
399: 
400:             // 点暂停阻塞
401:             if (Signal.WaitStart() == false)
402:             {
403:                 return ExcuteResult.Abort;
404:             }
405: 
406:             return ExcuteResult.Success;

