191:         private void SortActionNodeByModule(WorkProcessEnum workProcess, WorkProcessModuleEnum workProcessModule)
192:         {
193:             switch (workProcess)
194:             {
195:                 case WorkProcessEnum.TransportFirst:
196:                     if (workProcessModule == WorkProcessModuleEnum.StepFirst)
197:                     {
198:                         this.SortTransportFirsAndStepFirst();
199:                     }
200:                     else
201:                     {
202:                         this.SortTransportFirsAndPositionFirst();
203:                     }
204: 
205:                     break;
206: 
207:                 case WorkProcessEnum.SubstrateFirst:
208:                     if (workProcessModule == WorkProcessModuleEnum.StepFirst)
209:                     {
210:                         this.SortSubstrateFirsAndStepFirst();
211:                     }
212:                     else
213:                     {
214:                         this.SortSubstrateFirsAndPositionFirst();
215:                     }
216: 
217:                     break;
218: 
219:                 case WorkProcessEnum.ModuleFirst:
220:                     if (workProcessModule == WorkProcessModuleEnum.StepFirst)
221:                     {
222:                         this.SortModuleFirsAndStepFirst();
223:                     }
224:                     else
225:                     {
226:                         this.SortModuleFirsAndPositionFirst();
227:                     }
228: 
229:                     break;
230: 
231:                 case WorkProcessEnum.BondPositionFirst:
232:                     if (workProcessModule == WorkProcessModuleEnum.StepFirst)
233:                     {
234:                         this.SortBondPositionFirsAndStepFirst();
235:                     }
236:                     else
237:                     {
238:                         this.SortBondPositionFirsAndPositionFirst();
239:                     }
240: 
241:                     break;
242:             }
243: 
244:             // 如果是分段的情况下
245:             if (ProductConfiguration.GetInstance().TransportUnitConfig.SubstrateProcessing == SubstrateProcessingEnum.Divide)
246:             {
247:                 //// TODO 这样直接分段是有问题的，后续更改
248:                 //int divideSubstrate = ProductConfiguration.GetInstance().SubstrateConfig.Count / 2;
249:                 //List<ActionNodeMessage> first = this.WorkMessages.FindAll(it => it.Substrate > divideSubstrate);
250:                 //first.Add(new ActionNodeMessage(DispenseActionNodes.InteractiveAction.Name, 0, 0, ""));
251:                 //List<ActionNodeMessage> last = this.WorkMessages.FindAll(it => it.Substrate <= divideSubstrate);
252: 
253:                 //// 找到中间的行列数
254:                 //int divideNumber = ProductConfiguration.GetInstance().SubstrateConfig.ColumnCount / 2;
255: 
256:                 //this.WorkMessages.Clear();
257:                 //this.WorkMessages.AddRange(first);
258:                 //this.WorkMessages.AddRange(last);
259: 
260: 
261:                 List<int> first = TuService.GetFirstMatrixIndex();
262: 
263:                 List<ActionNodeMessage> firstActionNodeMessages = new List<ActionNodeMessage>();
264: 
265:                 List<ActionNodeMessage> lastActionNodeMessages = new List<ActionNodeMessage>();
266: 
267:                 while (this.WorkMessages.Count != 0)
268:                 {
269:                     if (first.Contains(this.WorkMessages[0].Substrate))
270:                     {
271:                         firstActionNodeMessages.Add(this.WorkMessages[0]);
272:                         this.WorkMessages.RemoveAt(0);
273:                     }
274:                     else
275:                     {
276:                         lastActionNodeMessages.Add(this.WorkMessages[0]);
277:                         this.WorkMessages.RemoveAt(0);
278:                     }
279:                 }
280: 
281:                 this.WorkMessages.AddRange(lastActionNodeMessages);
282: 
283:                 this.WorkMessages.Add(new ActionNodeMessage(DispenseActionNodes.InteractiveAction.Name, 0, 0, null));
284: 
285:                 this.WorkMessages.AddRange(firstActionNodeMessages);
286:             }
287:         }
