884:         /// <summary>
885:         /// 移除其他步骤
886:         /// </summary>
887:         public void RemoveOtherStep()
888:         {
889:             if (!ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
890:             {
891:                 return;
892:             }
893: 
894:             OppositeSex tuOppositeSex = ProductConfiguration.GetInstance().OppositeSexConfiguration.OppositeSexConfigs;
895:             for (int i = 0; i < this.WorkMessages.Count; i++)
896:             {
897:                 if (this.WorkMessages[i].Substrate == 0)
898:                 {
899:                     continue;
900:                 }
901: 
902:                 if (tuOppositeSex.DownConfigs.Count < this.WorkMessages[i].Substrate)
903:                 {
904:                     this.WorkMessages.RemoveAt(i);
905:                     i--;
906:                     continue;
907:                 }
908: 
909:                 if (this.WorkMessages[i].Module == 0)
910:                 {
911:                     continue;
912:                 }
913: 
914:                 if (tuOppositeSex.DownConfigs[this.WorkMessages[i].Substrate - 1].DownConfigs.Count < this.WorkMessages[i].Module)
915:                 {
916:                     this.WorkMessages.RemoveAt(i);
917:                     i--;
918:                     continue;
919:                 }
920: 
921:                 OppositeSex bondOppositeSex = tuOppositeSex.DownConfigs[this.WorkMessages[i].Substrate - 1]
922:                     .DownConfigs[this.WorkMessages[i].Module - 1];
923: 
924:                 SingleProcessStep singleProcessStep = this.ProcessSteps.Find(it => it.ProcessStepName == this.WorkMessages[i].ProcessStepName);
925: 
926:                 if (singleProcessStep == null)
927:                 {
928:                     continue;
929:                 }
930: 
931:                 if (!bondOppositeSex.DownConfigs.Exists(it => it.Name == singleProcessStep.BondPositionName))
932:                 {
933:                     this.WorkMessages.RemoveAt(i);
934:                     i--;
935:                 }
936:             }
937:         }

