77:                 {
78:                     return ExcuteResult.Alarm;
79:                 }
80: 
81:                 // 如果在预点胶的时候点了停止则退出
82:                 if (!Signal.WaitStart())
83:                 {
84:                     return ExcuteResult.Fail;
85:                 }
86: 
87:                 // 获取需要执行的图案
88:                 EpoxyApplication correctApplication = this.ActionNodeController.CurrentEpoxyApplication;
89: 
90:                 AKRSPoint3D point = bondPosition.CoordinateSystem.SelfPosToG0(new AKRSPoint3D(correctApplication.OffsetX, correctApplication.OffsetY, 0));
91: 
92:                 DispenseRunTimeProvider.RecordTime("系统1点胶动作执行", $"点胶的焊点位置为{point}");
93: 
94:                 point += bondPosition.GetDispensePositionCompensate() + DispenseDevicePara.GetInstance().DispenseModulePara.DispenseOffset;
95: 
96:                 DispenseRunTimeProvider.RecordTime("系统1点胶动作执行", $"点胶的真实位置为{point}");
97: 
98:                 // 空跑模式不出胶
99:                 bool isDrip = MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle;
100: 
101:                 double angle = bondPosition.CoordinateSystem.DegreeInG0() * 180.0 / Math.PI + bondPosition.GetDispenseRotaryCompensate();
102: 
103:                 DispenseRunTimeProvider.RecordTime("系统1点胶动作执行", $"点胶的角度为{angle}");
104: 
105:                 // 执行点胶
106:                 if (System1Domain.GetInstance().DispenseController.InterpolationApplication(correctApplication, point, isDrip, false, angle) != ExcuteResult.Success)
107:                 {
108:                     return ExcuteResult.Alarm;
109:                 }
110: 
111:                 // 修改当前焊点的状态为点胶完成
112:                 bondPosition.S1FinishedStep(this.ActionNodeController.SingleProcessStepName);
113: 
114:                 DispenseRunTimeProvider.RecordTime("系统1点胶动作执行", $"点胶动作结束");
115: 
116:                 StatisticsDomain.GetInstance().RefreshDispenseStatistics();
117: 
118:                 #region 点胶完之后看点胶效果
119: 
