125: 
126:                     System1Domain.GetInstance().DispenseController.MoveToG0Pos3D(visionPos);
127: 
128:                     while (MachineStateModel.GetInstance().IsVisionPreviousBondPositionInSystem1)
129:                     {
130:                         if (Machine.GetInstance().IsStop())
131:                         {
132:                             MachineStateModel.GetInstance().IsVisionPreviousBondPositionInSystem1 = false;
