96:         public bool System1MatterVision(BaseMatter baseEntity, bool byMapping = true)
97:         {
98:             // 如果没有开启定位，直接退出
99:             if (baseEntity.Config.LocateConfig.AdjustType == AdjustTypeEnum.None)
100:             {
101:                 baseEntity.BaseInfo.IsVisioned = true;
102:                 return true;
103:             }
104: 
105:             // 被屏蔽则不做
106:             if (baseEntity.MatterProductState == MatterProductState.Disable
107:                 && byMapping)
108:             {
109:                 return true;
110:             }
111: 
112:             bool visionAlarm = false;
113: 
114:             RetryCommand:
115: 
116:             // P1定位
117:             if (!this.System1VisionByPos(baseEntity, TuService.NormalVisionType.P1Vision, visionAlarm))
118:             {
119:                 return false;
120:             }
121: 
122:             if (baseEntity.Config.LocateConfig.AdjustType == AdjustTypeEnum.OnePoint && baseEntity.EntityState != EntityState.Fail)
123:             {
124:                 // 纠偏计算
125:                 TuService.UpdateEntity(baseEntity, TuService.NormalVisionType.P1Vision);
126:                 return true;
127:             }
128: 
129:             // P2定位
130:             if (!this.System1VisionByPos(baseEntity, TuService.NormalVisionType.P2Vision, visionAlarm))
131:             {
132:                 return false;
133:             }
134: 
135:             if (baseEntity.Config.LocateConfig.AdjustType == AdjustTypeEnum.TwoPoints && baseEntity.EntityState != EntityState.Fail)
136:             {
137:                 if (!visionAlarm)
138:                 {
139:                     // 距离检查
140:                     DialogResult dialogResult = VisionService.DistanceCheck(baseEntity);
141: 
142:                     if (dialogResult == DialogResult.Abort)
143:                     {
144:                         Machine.GetInstance().Stop();
145:                         return false;
146:                     }
147:                     else if (dialogResult == DialogResult.Retry)
148:                     {
149:                         visionAlarm = true;
150:                         goto RetryCommand;
151:                     }
152:                     else if (dialogResult == DialogResult.None)
153:                     {
154:                         baseEntity.MatterProductState = MatterProductState.Disable;
155:                     }
156:                 }
157:                 
158:                 // 纠偏计算
159:                 TuService.UpdateEntity(baseEntity, TuService.NormalVisionType.P2Vision);
160: 
161:                 return true;
162:             }
163: 
164:             // P3定位
165:             if (!this.System1VisionByPos(baseEntity, TuService.NormalVisionType.P3Vision))
166:             {
167:                 return false;
