297:             {
298:                 this.StopSearch();
299: 
300:                 // 在范围内
301:                 if (this.IsInSearchRange(this.nextDie.Pos))
302:                 {
303:                     if (this.nextDie.Exist)
304:                     {
305:                         // 确认存在的晶片视觉定位确认前就可以取
306:                         this.RecurCount = 0;
307:                         this.currentDie = this.nextDie;
308:                         this.matchResult = this.currentDie.MatchResult;
309:                         this.MoveDieToPickCenter();
310:                         return true;
311:                     }
312:                     else
313:                     {
314:                         this.CalculateDiesPosition();
315:                         if (this.nineDie.CenterDie.Exist)
316:                         {
317:                             this.nextDie = this.nineDie.CenterDie;
318: 
