321:                             {
322:                                 return this.NextDie();
323:                             }
324: 
325:                             this.currentDie = this.nextDie;
326:                             this.RecurCount = 0;
327:                             this.matchResult = this.currentDie.MatchResult;
328:                             this.MoveDieToPickCenter();
329:                             return true;
330:                         }
331:                         else
332:                         {
333:                             if (this.RecurCount > this.RecurLimit)
334:                             {
335:                                 //AKRSMessageBoxExt.Show(
336:                                 //    $"Block search nine recurCount is out limit - {this.RecurLimit}!",
337:                                 //    "Error",
338:                                 //    new string[] { "OK" },
339:                                 //    new DialogResult[] { DialogResult.OK });
340:                                 AKRSMessageBoxExt.Show(
341:                                     $"智能搜索超出递归次数 - {this.RecurLimit}!",
342:                                     "Error",
343:                                     new string[] { "OK" },
344:                                     new DialogResult[] { DialogResult.OK });
345:                                 throw new PickRefEnd();
346:                             }
347: 
348:                             this.countBlankNum++;
349:                             this.RecurCount++;
350:                             
351:                             return this.NextDie();
352:                         }
353:                     }
354:                 }
355:                 else
356:                 {
357:                     if (this.RecurCount > this.RecurLimit)
358:                     {
359:                         //AKRSMessageBoxExt.Show(
360:                         //    $"Block search nine recurCount is out limit - {this.RecurLimit}!",
361:                         //    "Error",
362:                         //    new string[] { "OK" },
363:                         //    new DialogResult[] { DialogResult.OK });
364:                         AKRSMessageBoxExt.Show(
365:                             $"智能搜索超出递归次数 - {this.RecurLimit}!",
366:                             "Error",
367:                             new string[] { "OK" },
368:                             new DialogResult[] { DialogResult.OK });
369:                         throw new PickRefEnd();
370:                     }
371: 
372:                     this.countBlankNum++;
373:                     this.RecurCount++;
374:                     
375:                     return this.NextDie();
376:                 }
377:             }
378:             catch (PickRefEnd e)
379:             {
380:                 throw new PickRefEnd();
381:             }
382:             catch (Exception e)
383:             {
384:                 throw;
385:             }
386:         }

