587:         private ExcuteResult Pick(
588:             double pickLevel,
589:             PickTypeEnum pickType)
590:         {
591:             try
592:             {
593:                 if (MachineStateModel.GetInstance().IsCompensateWork)
594:                 {
595:                     return ExcuteResult.Success;
596:                 }
597: 
598:                 System2RunTimeProvider.RecordTime("Pick", "开始Pick动作 ");
599: 
600:                 PickActionParameter pickActionParameter =
601:                     this.pickActionProvider.GetPickActionParameter(component, pickType);
602: 
603:                 // 取片准备位
604:                 double pickPreLevel = pickLevel + pickActionParameter.SlowTravelDistanceBeforePickup;
605: 
606:                 // 预备抬起位
607:                 double liftPreLevel = pickLevel + pickActionParameter.SlowTravelDistanceAfterPickup;
608: 
609:                 this.pickActionProvider.SlowDownToPickLevel(pickLevel, pickActionParameter);
610: 
611:                 System2RunTimeProvider.RecordTime(
612:                     "Pick",
613:                     $"取片动作--焊头移动到取料高度: {pickPreLevel}完成, Speed: {pickActionParameter.SlowTravelSpeedBeforePickup}");
614: 
615:                 // 吸嘴吸真空打开
616:                 this.bondHeadController.OpenToolVaccum();
617: 
618:                 System2RunTimeProvider.RecordTime("Pick", $"打开吸嘴真空完成");
619: 
620:                 // 关平台真空
621:                 pickActionParameter.VacuumElectric?.SetOutputValue(false);
622: 
623:                 System2RunTimeProvider.RecordTime("Pick", $"关平台真空完成");
624: 
625:                 // 翻转台吹气
626:                 if (pickType == PickTypeEnum.FlipTable && this.flipModuleProgram.CurrentFlipTool.BlowDelay > 0)
627:                 {
628:                     this.flipTableController.Blow(
629:                         this.flipModuleProgram.CurrentFlipTool.BlowProportion,
630:                         this.flipModuleProgram.CurrentFlipTool.BlowDelay);
631: 
632:                     System2RunTimeProvider.RecordTime("Pick", $"翻转台以{this.flipModuleProgram.CurrentFlipTool.BlowProportion}的比例吹气{this.flipModuleProgram.CurrentFlipTool.BlowDelay}ms 完成");
633:                 }
634: 
635:                 // 记录取片力值
636:                 this.RecordLastPickForce();
637: 
638:                 System2RunTimeProvider.RecordTime("Pick", $"读取并记录取片压力完成");
639: 
640:                 // 顶针动作
641:                 if (pickType == PickTypeEnum.CarrierWithWafer)
642:                 {
643:                     this.EjectionLift();
644: 
645:                     System2RunTimeProvider.RecordTime(
646:                         "Pick",
647:                         $"顶针顶起完成,顶针G0坐标{WaferSubController.GetInstance().EjectController.EjectionAxisZG0Pos.Z}");
648:                 }
649: 
650:                 // 拾取延迟
651:                 DelayHelper.Delay(pickActionParameter.PickDelay);
652: 
653:                 System2RunTimeProvider.RecordTime("Pick", $"拾取延时{pickActionParameter.PickDelay} ms 完成");
654: 
655:                 // 结束力控读取
656:                 UcMainSystem.ActiveReadBondForce(false);
657: 
658:                 // 晶圆芯片同步顶的情况下不执行低速上抬动作
659:                 if ((component is CarrierWithWaferConfig wafer && wafer.IsActivateSynchronousEjection) == false)
660:                 {
661:                     // 焊头低速上抬
662:                     this.SlowUpToLiftLevel(liftPreLevel, pickActionParameter);
663: 
664:                     System2RunTimeProvider.RecordTime("Pick", $"焊头低速上抬结束");
665:                 }
666: 
667:                 System2RunTimeProvider.RecordTime("Pick", $"取片动作完成");
668:             }
669:             catch (NullReferenceException e)
670:             {
671:                 LogHelper.Post(Level.Error, $"获取力控配置参数失败", e, LogCategory.Bond);
672: 
673:                 DialogResult dialogResult = AKRSMessageBoxExt.Show(
674:                     $"取片动作-获取力控配置参数失败，将退出自动工作! \r\n" + e.ToString(),
675:                     "取片报警",
676:                     new string[] { "确认" },
677:                     new DialogResult[] { DialogResult.OK },
678:                     AlarmLevel.SecondLevel);
679: 
680:                 throw;
681:             }
682:             catch (Exception ex)
683:             {
684:                 LogHelper.Post(Level.Error, $"取料失败", ex, LogCategory.Bond);
685: 
686:                 DialogResult dialogResult = AKRSMessageBoxExt.Show(
687:                     $"取片失败，将退出自动工作! \r\n" + ex.ToString(),
688:                     "取片报警",
689:                     new string[] { "确认" },
690:                     new DialogResult[] { DialogResult.OK },
691:                     AlarmLevel.SecondLevel);
692: 
693:                 throw;
694:             }
695: 
696:             return ExcuteResult.Success;
697:         }
