699:         /// <summary>
700:         /// 记录最终贴片力
701:         /// </summary>
702:         private void RecordLastPickForce()
703:         {
704:             if (this.component.PickupForceMode != ForceModeEnum.Force)
705:             {
706:                 return;
707:             }
708: 
709:             // etel机台没办法读模拟量
710:             if (System2Module.GetInstance().BondModule.BondHead.AxisZ.AxisDrive is ETELAxis)
711:             {
712:                 return;
713:             }
714: 
715:             double angle = this.bondHeadController.GetAxisTRealPos();
716: 
717:             bool isSmallForce = ForceCalibrationService.JudgeIsSmallForce(this.component.PickupForce);
718: 
719:             double readForce = this.bondHeadController.GetBondForceCurrentVal(isSmallForce);
720: 
721:             double forecIncrement = readForce - System2RunTimeProvider.BondHeadInitialVal;
722: 
723:             // 记录力值
724:             this.bp.BondPositionInfo.ActualPickForce =
725:                 ForceCalibrationService.ForceIncrementToActualForce(forecIncrement, isSmallForce, angle);
726:         }
727:     }

