724: 
725:                 System2RunTimeProvider.RecordTime("Pick", $"顶针同步顶完成");
726:             }
727:             else
728:             {
729:                 this.StartAsynchronousCollectionLVDT();
730: 
731:                 // 这里改成异步是为了提高UPH
732:                 Task ejectTask = Task.Run(
733:                      () =>
734:                          {
735:                              System2RunTimeProvider.RecordTime(
736:                                  "Pick",
737:                                  $"顶针准备顶起，顶针G0坐标{WaferSubController.GetInstance().EjectController.EjectionAxisZG0Pos.Z}");
738: 
739:                              System2RunTimeProvider.EjectStopwatch.Restart();
740: 
741:                              // 顶针顶起
742:                              WaferSubController.GetInstance().EjectController.MoveEjectToLiftPosition();
743: 
744:                              System2RunTimeProvider.EjectionLiftTime.Add(
745:                                  new()
746:                                  {
747:                                      time = DateTime.Now,
748:                                      liftTime = System2RunTimeProvider.EjectStopwatch.ElapsedMilliseconds
749:                                  });
750:                          });
751: 
752:                 if (component.IsResetForceControlAdvanceDuringPickup
753:                     && component.PickupForceMode == ForceModeEnum.Force)
754:                 {
