756:                     double pos = this.bondHeadController.GetAxisZRealPos()
757:                                  + carrierWithWafer.ForecResetDistanceDuringForceMode;
758: 
759:                     // 原地退出力控
760:                     this.bondHeadController.ForceControlReset(pos, this.initialSpeed);
761: 
762:                     System2RunTimeProvider.RecordTime("Pick", $"原地退出力控完成");
763:                 }
764: 
