786:             }
787: 
788:             if (this.component.PickupForceMode == ForceModeEnum.Force)
789:             {
790:                 bool isSmallForce = ForceCalibrationService.JudgeIsSmallForce(this.component.PickupForce);
791: 
792:                 this.bondHeadController.ZeroBondhead(isSmallForce);
