400:         private void SlowUpToLiftLevel(double liftPreLevel, BondActionParameter bondActionParameter)
401:         {
402:             if (component.BondingForceMode == ForceModeEnum.Distance)
403:             {
404:                 if (component.IsActivateSlowTravelAfterBonding)
405:                 {
406:                     // 低速上抬到预固晶位
