413:                     System2RunTimeProvider.RecordTime(
414:                         "Bond",
415:                         $"距离模式低速上抬完成，速度{bondActionParameter.SlowTravelSpeedAfterPlace}");
416:                 }
417:             }
418:             else
419:             {
420:                 if (component.IsActivateSlowTravelAfterBonding)
421:                 {
422:                     // 加这句是为了防止Z轴抬起时没有恢复正常速度
423:                     this.bondHeadController.SetAxisZSpeed(bondActionParameter.SlowTravelSpeedAfterPlace);
